-- 1132: Blog post — "SC-300 Identity and Access Administrator in Singapore: Exam Domains, Funding and Practice Exams"
--
--       Lead-in post for WSQ - Microsoft Identity and Access Administrator (SC-300) (TGS-2024047021).
--       Backdated to 2025-10-17 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $2,000.00, GST $180.00 (9%), baseline nett $1,180.00
--     (SG/PR 21+, 50%), MCES/SME nett $780.00 (SG 40+, 70%).
--   * Course information: 4 days / 32 hrs, Intermediate, 2 hrs assessment.
--   * Skills Framework: Security Strategy (ICT-SNA-6021-1.1).
--   * Exam weightings from the official study guide, skills measured as of 27 Apr 2026.
--   * Practice-exam URL verified HTTP 200: https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-sc-300
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'SC-300 Identity and Access Administrator in Singapore: Exam Domains, Funding and Practice Exams', 'sc-300-identity-and-access-administrator-singapore-guide', 'SC-300 is the Microsoft credential for IT and security staff running Microsoft Entra ID and Conditional Access. This guide walks the exam domains and their weightings, sets out exactly what you pay after WSQ funding &mdash; $1,180 nett, or $780 for Singapore Citizens aged 40 and above &mdash; and shows what the 4 days course covers.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>SC-300</strong> is the Microsoft credential for IT and security staff running Microsoft Entra ID and Conditional Access. This guide covers what the exam measures, what the 4 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$1,180</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$780</strong> for Singapore Citizens aged 40 and above.</p></div><h2>Why SC-300 is worth sitting</h2><p>Identity is the security perimeter now. Nearly every significant breach involves credentials somewhere in the chain, and in Microsoft environments the controls that matter &mdash; Conditional Access, multifactor authentication, privileged access management &mdash; all live in Entra ID. SC-300 certifies you can run them.</p><ul><li><strong>Authentication and access management is the heaviest domain</strong> at 25&ndash;30%, covering Conditional Access, MFA and passwordless.</li><li><strong>Identity governance is covered properly</strong> &mdash; access reviews, entitlement management and privileged access.</li><li><strong>Hybrid identity is included</strong>, which matters for the many Singapore organisations still running Entra Connect alongside on-premise AD.</li><li><strong>It pairs directly with SC-200</strong> for a complete security-operations skill set.</li></ul><p>The course is mapped to the Skills Framework under <strong>Security Strategy</strong> (TSC code ICT-SNA-6021-1.1), and leads to roles such as Identity and Access Administrator, IT Security Specialist, Microsoft Entra Specialist, Systems Administrator. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-identity-and-access-administrator-sc-300.html">Check the funding you qualify for</a>.</p><h2>The SC-300 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>SC-300: Microsoft Identity and Access Administrator</td></tr><tr><td>Length</td><td>100 minutes</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled &mdash; not 70%)</td></tr><tr><td>Certification</td><td>Identity and Access Administrator Associate</td></tr><tr><td>Renewal</td><td>Free online renewal every 12 months</td></tr></tbody></table><h2>SC-300 exam domains and weightings</h2><p>These are the skills measured on the official study guide. The weightings tell you where to spend your revision time.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Implement and manage user identities</td><td>20&ndash;25%</td></tr><tr><td>Implement authentication and access management</td><td>25&ndash;30%</td></tr><tr><td>Plan and implement workload identities</td><td>20&ndash;25%</td></tr><tr><td>Plan and automate identity governance</td><td>20&ndash;25%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 27 Apr 2026.</em></p><h2>What the WSQ course covers</h2><p>The 4 days (32 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-identity-and-access-administrator-sc-300.html"><strong>WSQ - Microsoft Identity and Access Administrator (SC-300)</strong></a> course is pitched at <strong>Intermediate</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Explore identity in Microsoft Entra ID</li><li>Implement initial configuration of Microsoft Entra ID</li><li>Create, configure, and manage identities</li><li>Implement and manage external identities</li><li>Implement and manage hybrid identity</li><li>Secure Microsoft Entra users with multifactor authentication</li><li>Manage user authentication</li><li>Plan, implement, and administer Conditional Access</li><li>Manage Microsoft Entra Identity Protection</li><li>Implement access management for Azure resources</li><li>Plan and design the integration of enterprise apps for SSO</li><li>Implement and monitor the integration of enterprise apps for SSO</li><li>Implement app registration</li><li>Plan and implement entitlement management</li></ol><p>The full outline runs to 17 topics &mdash; see the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-identity-and-access-administrator-sc-300.html">course page</a> for the complete list.</p><h2>Practise before you book the exam</h2><p>Course participants get free, unlimited access to our <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-sc-300">SC-300 practice exams</a> on the Tertiary Infotech Practice Exam Portal, in both Practice Mode (with instant explanations) and timed Exam Mode. The portal offers non-participants 10 free questions per exam.</p><h2>What you actually pay: funding for SC-300 training</h2><p>The full fee is $2,000 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$2,180</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$1,180</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$780</strong></td></tr></tbody></table><p><em>GST of $180 is charged at 9% on the full course fee of $2,000, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-identity-and-access-administrator-sc-300.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>Your route to certification</h2><ol><li><strong>Register for the 4 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-identity-and-access-administrator-sc-300.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li><li><strong>Book and sit SC-300</strong> through Pearson VUE. The certification exam is booked and paid for separately from the course.</li></ol><h2>Where to go after SC-300</h2><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-security-operations-analyst-sc-200.html">SC-200</a> covers the detection and response side, and SC-100 is the architect-level cybersecurity certification that builds on both. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need security experience before SC-300?</summary><div class="mmd-faq-a"><p>This is an intermediate-level course. Familiarity with Microsoft 365 or Azure administration is assumed, though deep security experience is not required.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does this cover Conditional Access in depth?</summary><div class="mmd-faq-a"><p>Yes. Conditional Access sits in the authentication and access management domain, which is the heaviest on the exam at 25&ndash;30%, and is covered hands-on.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the exam fee included?</summary><div class="mmd-faq-a"><p>No. The course fee covers training and the WSQ assessment. The SC-300 exam is booked separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">How does SC-300 differ from SC-200?</summary><div class="mmd-faq-a"><p>SC-300 is about identity &mdash; who gets access to what. SC-200 is about security operations &mdash; detecting and responding to threats once they occur.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does the certification expire?</summary><div class="mmd-faq-a"><p>Yes, annually, with free online renewal through Microsoft Learn.</p></div></details></div><h2>Register for Identity and Access Administrator training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-identity-and-access-administrator-sc-300.html"><strong>WSQ - Microsoft Identity and Access Administrator (SC-300)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-10-17', 'TGS-2024047021', 'TGS-2024047021', 'SC-300 Course Singapore | Identity and Access Administrator | WSQ Funding', 'Train for SC-300 Identity and Access Administrator in Singapore. 4 days WSQ course from $780 nett after funding, full exam domain breakdown, and free practice exams for participants.', 'sc-300 course singapore, identity and access administrator certification, sc-300 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, sc-300 funding, sc-300 training singapore', 'manual-skip-no-share', '2025-10-17 09:00:00', '2025-10-17 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'sc-300-identity-and-access-administrator-singapore-guide');

